    ReplayStreamPacketBodyCase ReplayStreamPacket::BodyCase() const
    {
        switch (Body.index())
        {
            case 1:
                return ReplayStreamPacketBodyCase::Start;
            case 2:
                return ReplayStreamPacketBodyCase::Chunk;
            case 3:
                return ReplayStreamPacketBodyCase::Checkpoint;
            case 4:
                return ReplayStreamPacketBodyCase::End;
            case 5:
                return ReplayStreamPacketBodyCase::Failure;
            case 6:
                return ReplayStreamPacketBodyCase::ResumeRequest;
            case 7:
                return ReplayStreamPacketBodyCase::ResumeResponse;
            case 8:
                return ReplayStreamPacketBodyCase::Ack;
            default:
                return ReplayStreamPacketBodyCase::None;
        }
    }

